    d['separation']={'cases':[{'name':'A • Sand recovery','mixture':'Sand + water','target':'Sand','choices':[{'method':'Filter','correct':True,'feedback':'Sand remains as residue; water passes through.'},{'method':'Open evaporation only','correct':False,'feedback':'This could eventually leave sand, but filtration directly separates the insoluble grains and is the intended efficient route.'},{'method':'Condense only','correct':False,'feedback':'There is no vapour to condense in the stated mixture.'}],'stages':['Sand + water','Filter retains sand','Sand residue collected']},{'name':'B • Salt recovery','mixture':'Saltwater','target':'Salt','choices':[{'method':'Evaporate water','correct':True,'feedback':'Water leaves and the dissolved salt remains.'},{'method':'Ordinary filtration','correct':False,'feedback':'Dissolved salt passes with water through ordinary filter paper.'},{'method':'Keep only condensed water','correct':False,'feedback':'That collects water rather than the salt target.'}],'stages':['Salt solution','Water evaporates','Salt remains']},{'name':'C • Water recovery','mixture':'Saltwater','target':'Water','choices':[{'method':'Evaporate, capture and condense','correct':True,'feedback':'Water vapour is captured and cooled into collected liquid water.'},{'method':'Open evaporation','correct':False,'feedback':'The target water escapes into the room.'},{'method':'Ordinary filtration','correct':False,'feedback':'Salt remains dissolved in the filtered liquid.'}],'stages':['Salt solution','Water vapour captured','Vapour cools','Liquid water collected']},{'name':'D • Two separate solids','mixture':'Sand + saltwater','target':'Sand and salt separately','choices':[{'method':'Filter, then evaporate the filtrate','correct':True,'feedback':'Sand is collected as residue; removing water from the saltwater filtrate leaves salt separately.'},{'method':'Evaporate first and stop','correct':False,'feedback':'This leaves sand and salt together, not separately.'},{'method':'Filter and discard the filtrate','correct':False,'feedback':'Discarding the filtrate loses the dissolved salt target.'}],'stages':['Sand + saltwater','Sand retained by filter','Saltwater filtrate collected','Water evaporates','Salt collected separately']}],'note':'Process schematic only. No heating or apparatus assembly is instructed; use the equivalent paper briefs.'}
